export const BRIEF = [{"id":"data_stale:BER","kind":"data_stale","severity":"critical","hotel_code":"BER","hotel_name":"Tessera Berlin Mitte","impact_eur":null,"impact_basis":"not priced: figures from this source are incomplete until it syncs again","sources":["hotel.data_sources"],"facts":{"system":"POS","vendor":"Lightspeed","status":"stale","last_sync_at":"2026-11-17 04:12","days_behind":3},"sql":"select d.hotel_code, h.name as hotel_name, null::float8 as impact_eur, d.system, d.vendor, d.status,\n       to_char(d.last_sync_at, 'YYYY-MM-DD HH24:MI') as last_sync_at,\n       (hotel.business_date() - d.last_sync_at::date) as days_behind\n  from hotel.data_sources d join hotel.hotels h using (hotel_code)\n where d.status <> 'ok'"},{"id":"account_loss:NYC","kind":"account_loss","severity":"warning","hotel_code":"NYC","hotel_name":"Arbor New York Midtown","impact_eur":-1336633,"impact_basis":"room revenue in the last 6 months vs the 6 months before","sources":["hotel.reservation_nights","hotel.reservations","hotel.accounts"],"facts":{"account":"Vantor Consulting","account_type":"corporate","room_nights_last_6m":450,"room_nights_previous_6m":5414,"last_stay":"2026-07-15"},"sql":"with bd as (select hotel.business_date() as d),\nx as (\n  select n.hotel_code, a.name as account, a.account_type,\n         count(*) filter (where n.stay_date >= bd.d - 182) as cur, count(*) filter (where n.stay_date < bd.d - 182) as prev,\n         sum(n.room_revenue) filter (where n.stay_date >= bd.d - 182) as rcur,\n         sum(n.room_revenue) filter (where n.stay_date < bd.d - 182) as rprev,\n         max(n.stay_date) as last_stay\n    from bd, hotel.reservation_nights n\n    join hotel.reservations r using (reservation_id)\n    join hotel.accounts a using (account_id)\n   where n.stay_date between bd.d - 364 and bd.d - 1 and a.account_type in ('corporate', 'wholesaler')\n   group by 1, 2, 3)\nselect x.hotel_code, h.name as hotel_name,\n       round((coalesce(x.rcur, 0) - x.rprev) * hotel.eur_rate(h.currency, (select d from bd)))::float8 as impact_eur,\n       x.account, x.account_type, x.cur::int as room_nights_last_6m, x.prev::int as room_nights_previous_6m,\n       to_char(x.last_stay, 'YYYY-MM-DD') as last_stay\n  from x join hotel.hotels h using (hotel_code)\n where x.prev >= 500 and x.cur < 0.5 * x.prev"},{"id":"gop_miss:MIA","kind":"gop_miss","severity":"warning","hotel_code":"MIA","hotel_name":"Lumen Miami Beach","impact_eur":-163656,"impact_basis":"GOP actual − budget in the last closed month, in EUR","sources":["hotel.pnl_monthly"],"facts":{"month":"2026-10","gop_var_pct":-20.6,"revenue_var_pct":-8.1,"gop_margin_pct":25.8,"gop_margin_budget_pct":29.8},"sql":"with m as (select max(month) as month from hotel.pnl_monthly where scenario = 'actual'),\nx as (\n  select p.hotel_code, m.month,\n         sum(p.amount * hotel.eur_rate(p.currency, p.month)) filter (where p.scenario = 'actual' and p.line = 'GOP') as gop,\n         sum(p.amount * hotel.eur_rate(p.currency, p.month)) filter (where p.scenario = 'budget' and p.line = 'GOP') as gop_b,\n         sum(p.amount * hotel.eur_rate(p.currency, p.month)) filter (where p.scenario = 'actual' and p.line = 'TOTAL_REVENUE') as rev,\n         sum(p.amount * hotel.eur_rate(p.currency, p.month)) filter (where p.scenario = 'budget' and p.line = 'TOTAL_REVENUE') as rev_b\n    from m join hotel.pnl_monthly p on p.month = m.month\n   where p.line in ('GOP', 'TOTAL_REVENUE') and p.scenario in ('actual', 'budget')\n   group by 1, 2)\nselect x.hotel_code, h.name as hotel_name, round(x.gop - x.gop_b)::float8 as impact_eur, to_char(x.month, 'YYYY-MM') as month,\n       round(100 * (x.gop - x.gop_b) / x.gop_b, 1)::float8 as gop_var_pct,\n       round(100 * (x.rev - x.rev_b) / x.rev_b, 1)::float8 as revenue_var_pct,\n       round(100 * x.gop / x.rev, 1)::float8 as gop_margin_pct, round(100 * x.gop_b / x.rev_b, 1)::float8 as gop_margin_budget_pct\n  from x join hotel.hotels h using (hotel_code)\n where x.gop_b > 0 and x.gop < 0.9 * x.gop_b"},{"id":"rooms_out_of_order:BCN","kind":"rooms_out_of_order","severity":"warning","hotel_code":"BCN","hotel_name":"Lumen Barcelona Mar","impact_eur":-114789,"impact_basis":"out-of-order room nights in the next 30 days × last 30 days occupancy × ADR","sources":["hotel.room_inventory_daily","hotel.v_hotel_day"],"facts":{"out_of_order_nights":798,"avg_rooms_out":25.7,"physical_rooms":300},"sql":"with bd as (select hotel.business_date() as d),\nlast30 as (\n  select hotel_code, sum(rooms_sold)::numeric / sum(rooms_available) as occ, sum(room_revenue_eur) / nullif(sum(rooms_sold), 0) as adr\n    from bd, hotel.v_hotel_day where date between bd.d - 30 and bd.d - 1 group by 1)\nselect i.hotel_code, h.name as hotel_name, -round(sum(i.out_of_order) * l.occ * l.adr)::float8 as impact_eur,\n       sum(i.out_of_order)::int as out_of_order_nights, round(avg(i.out_of_order), 1)::float8 as avg_rooms_out,\n       max(i.physical_rooms)::int as physical_rooms\n  from bd, hotel.room_inventory_daily i join hotel.hotels h using (hotel_code) join last30 l using (hotel_code)\n where i.date between bd.d and bd.d + 30\n group by i.hotel_code, h.name, l.occ, l.adr\nhaving avg(i.out_of_order) > 0.05 * max(i.physical_rooms)"},{"id":"web_conversion_drop:AMS","kind":"web_conversion_drop","severity":"warning","hotel_code":"AMS","hotel_name":"Arbor Amsterdam Centraal","impact_eur":-82004,"impact_basis":"direct bookings lost in the last 30 days at the earlier conversion rate × average booking value","sources":["hotel.web_daily"],"facts":{"device":"mobile","conversion_pct_last_30d":0.81,"conversion_pct_previous_60d":1.81},"sql":"with bd as (select hotel.business_date() as d),\nw as (\n  select hotel_code, device,\n         sum(sessions) filter (where date >= bd.d - 30) as s1, sum(bookings) filter (where date >= bd.d - 30) as b1,\n         sum(sessions) filter (where date < bd.d - 30) as s0, sum(bookings) filter (where date < bd.d - 30) as b0,\n         sum(booking_revenue) filter (where date < bd.d - 30) / nullif(sum(bookings) filter (where date < bd.d - 30), 0) as abv,\n         max(currency) as currency\n    from bd, hotel.web_daily where date between bd.d - 90 and bd.d - 1 group by 1, 2)\nselect w.hotel_code, h.name as hotel_name,\n       -round(((w.b0::numeric / w.s0) - (w.b1::numeric / w.s1)) * w.s1 * w.abv * hotel.eur_rate(w.currency, (select d from bd)))::float8 as impact_eur,\n       w.device, round(100.0 * w.b1 / w.s1, 2)::float8 as conversion_pct_last_30d,\n       round(100.0 * w.b0 / w.s0, 2)::float8 as conversion_pct_previous_60d\n  from w join hotel.hotels h using (hotel_code)\n where w.s1 > 1000 and (w.b1::numeric / w.s1) < 0.7 * (w.b0::numeric / w.s0)"},{"id":"staffing_gap:DPS","kind":"staffing_gap","severity":"warning","hotel_code":"DPS","hotel_name":"Lumen Bali Uluwatu","impact_eur":-53333,"impact_basis":"F&B revenue in the last 30 days vs the 30 days before","sources":["hotel.labor_daily","hotel.fnb_daily"],"facts":{"department":"Kitchen","staffing_pct":77.9},"sql":"with bd as (select hotel.business_date() as d),\ngap as (\n  select l.hotel_code, l.department, round(100.0 * sum(l.actual_hours) / sum(l.required_hours), 1) as staffing_pct\n    from bd, hotel.labor_daily l where l.date between bd.d - 30 and bd.d - 1\n   group by 1, 2 having sum(l.actual_hours) < 0.85 * sum(l.required_hours)),\nfnb as (\n  select f.hotel_code,\n         sum((f.food_revenue + f.beverage_revenue) * hotel.eur_rate(f.currency, f.date)) filter (where f.date >= bd.d - 30) as cur,\n         sum((f.food_revenue + f.beverage_revenue) * hotel.eur_rate(f.currency, f.date)) filter (where f.date < bd.d - 30) as prev\n    from bd, hotel.fnb_daily f where f.date between bd.d - 60 and bd.d - 1 group by 1)\nselect g.hotel_code, h.name as hotel_name,\n       case when g.department in ('Kitchen', 'F&B Service') then round(fnb.cur - fnb.prev)::float8 end as impact_eur,\n       g.department, g.staffing_pct::float8 as staffing_pct\n  from gap g join hotel.hotels h using (hotel_code) left join fnb using (hotel_code)"},{"id":"underpriced_demand:DXB2","kind":"underpriced_demand","severity":"warning","hotel_code":"DXB2","hotel_name":"Tessera Dubai Business Bay","impact_eur":42677,"impact_basis":"gap to the comp set median × rooms already sold on those nights: revenue already left on the table at today's rate. Booked rooms cannot be repriced; the rooms still unsold can.","sources":["hotel.v_rate_position","hotel.otb_as_of()","hotel.room_inventory_daily"],"facts":{"nights":3,"first_night":"2026-12-16","last_night":"2026-12-18","avg_bar_vs_comp":0.78,"most_comps_sold_out_on_one_night":3},"sql":"with bd as (select hotel.business_date() as d),\notb as (select o.* from bd, hotel.otb_as_of(bd.d, null, bd.d, bd.d + 45) o)\nselect r.hotel_code, h.name as hotel_name,\n       round(sum((r.comp_median - r.bar_rate) * coalesce(o.rooms_on_books, 0) * hotel.eur_rate(h.currency, r.stay_date)))::float8 as impact_eur,\n       count(*)::int as nights, to_char(min(r.stay_date), 'YYYY-MM-DD') as first_night, to_char(max(r.stay_date), 'YYYY-MM-DD') as last_night,\n       round(avg(r.bar_vs_comp), 2)::float8 as avg_bar_vs_comp, max(r.comps_sold_out)::int as most_comps_sold_out_on_one_night\n  from bd, hotel.v_rate_position r\n  join hotel.hotels h using (hotel_code)\n  join hotel.room_inventory_daily i on i.hotel_code = r.hotel_code and i.date = r.stay_date\n  left join otb o on o.hotel_code = r.hotel_code and o.stay_date = r.stay_date\n where r.stay_date between bd.d and bd.d + 45 and r.bar_vs_comp < 0.85\n   and (r.comps_sold_out >= 2 or coalesce(o.rooms_on_books, 0) > 0.7 * i.rooms_available)\n group by r.hotel_code, h.name\nhaving count(*) >= 2"},{"id":"pace_behind:LIS","kind":"pace_behind","severity":"warning","hotel_code":"LIS","hotel_name":"Arbor Lisbon Chiado","impact_eur":-38187,"impact_basis":"room revenue on the books vs the same point last year, next 45 nights","sources":["hotel.pace_vs_stly()"],"facts":{"pace_pct":-17.4,"rooms_otb":2231,"rooms_otb_stly":2700},"sql":"select p.hotel_code, h.name as hotel_name,\n       round(sum(p.revenue_otb - p.revenue_otb_stly) * hotel.eur_rate(h.currency, hotel.business_date()))::float8 as impact_eur,\n       round(100.0 * (sum(p.rooms_otb) - sum(p.rooms_otb_stly)) / nullif(sum(p.rooms_otb_stly), 0), 1)::float8 as pace_pct,\n       sum(p.rooms_otb)::int as rooms_otb, sum(p.rooms_otb_stly)::int as rooms_otb_stly\n  from hotel.pace_vs_stly(null, 45) p join hotel.hotels h using (hotel_code)\n group by p.hotel_code, h.name, h.currency\nhaving 100.0 * (sum(p.rooms_otb) - sum(p.rooms_otb_stly)) / nullif(sum(p.rooms_otb_stly), 0) <= -10"}] as const;
